"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["92042"],{11409(s){s.exports=JSON.parse('{"id":"V4-151","slug":"climate-risk","term":"Climate Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Climate risk is the risk of financial loss or harm arising from climate change, including both the physical effects of a changing climate and the effects of the transition to a low-carbon economy.","explanation":["Climate risk is usually divided into two main types. Physical risk comes from climate-related events and long-term changes, such as floods, storms, wildfires, droughts, heatwaves and rising sea levels. Transition risk comes from changes in policy, technology, markets and consumer preferences as economies shift away from fossil fuels.","Some frameworks also include liability risk, from legal claims against companies or governments for contributing to climate change or failing to disclose climate risks.","For example, a bank lending to coastal property developers faces physical risk from flooding, while a bank lending to coal mining companies faces transition risk if stricter emissions rules reduce demand for coal.","Climate risk has become a major focus for regulators, central banks and investors. Many jurisdictions now require or encourage companies and financial institutions to assess and disclose their climate risks, using frameworks such as the recommendations of the Task Force on Climate-related Financial Disclosures and the ISSB standards. Central banks run climate stress tests to assess the financial system\u2019s resilience."],"note":"","total":1725,"prev":{"slug":"clearing-house","term":"Clearing House"},"next":{"slug":"climate-stress-test","term":"Climate Stress Test"}}')}}]);